package com.smartgrocery.controller; import com.smartgrocery.entity.StoreOrder; import com.smartgrocery.repository.StoreOrderRepository; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*; @RestController @RequestMapping("/api/v1/orders") public class OrderController {private final StoreOrderRepository repo;public OrderController(StoreOrderRepository r){repo=r;} @GetMapping public List<StoreOrder> all(){return repo.findAll();} public record NewOrder(String customerName,BigDecimal total){} @PostMapping public StoreOrder create(@RequestBody NewOrder o){return repo.save(new StoreOrder(o.customerName(),o.total()));} @PutMapping("/{id}/status") public StoreOrder status(@PathVariable Long id,@RequestParam String value){StoreOrder o=repo.findById(id).orElseThrow();o.setStatus(value.toUpperCase());return repo.save(o);}}